INSERT INTO series(id_title,number_of_seasons) SELECT id_title,1 FROM titles WHERE type='TV Show' AND lower(title)=lower('The Cage') ORDER BY id_title LIMIT 1 ON CONFLICT(id_title) DO UPDATE SET number_of_seasons=excluded.number_of_seasons,deleted_at=NULL,updated_at=now();
INSERT INTO seasons(id_series,season_number,number_of_episodes) SELECT s.id_series,1,5 FROM series s JOIN titles t ON t.id_title=s.id_title WHERE t.type='TV Show' AND lower(t.title)=lower('The Cage') ORDER BY s.id_series LIMIT 1 ON CONFLICT(id_series,season_number) DO UPDATE SET number_of_episodes=excluded.number_of_episodes,deleted_at=NULL,updated_at=now();
INSERT INTO episodes(id_season,episode_number,title,description,duration) SELECT se.id_season,1,'The Open Mat','Taylor interrupts a champion''s training session and earns a painful chance to prove himself.',42 FROM seasons se JOIN series s ON s.id_series=se.id_series JOIN titles t ON t.id_title=s.id_title WHERE t.type='TV Show' AND lower(t.title)=lower('The Cage') AND se.season_number=1 ORDER BY se.id_season LIMIT 1 ON CONFLICT(id_season,episode_number) DO UPDATE SET title=excluded.title,description=excluded.description,duration=excluded.duration,deleted_at=NULL,updated_at=now();
INSERT INTO episodes(id_season,episode_number,title,description,duration) SELECT se.id_season,2,'Fight Camp','A veteran coach rebuilds Taylor''s technique while financial pressure follows him into the gym.',44 FROM seasons se JOIN series s ON s.id_series=se.id_series JOIN titles t ON t.id_title=s.id_title WHERE t.type='TV Show' AND lower(t.title)=lower('The Cage') AND se.season_number=1 ORDER BY se.id_season LIMIT 1 ON CONFLICT(id_season,episode_number) DO UPDATE SET title=excluded.title,description=excluded.description,duration=excluded.duration,deleted_at=NULL,updated_at=now();
INSERT INTO episodes(id_season,episode_number,title,description,duration) SELECT se.id_season,3,'First Contract','Taylor signs for a dangerous short-notice bout against an opponent with everything to lose.',43 FROM seasons se JOIN series s ON s.id_series=se.id_series JOIN titles t ON t.id_title=s.id_title WHERE t.type='TV Show' AND lower(t.title)=lower('The Cage') AND se.season_number=1 ORDER BY se.id_season LIMIT 1 ON CONFLICT(id_season,episode_number) DO UPDATE SET title=excluded.title,description=excluded.description,duration=excluded.duration,deleted_at=NULL,updated_at=now();
INSERT INTO episodes(id_season,episode_number,title,description,duration) SELECT se.id_season,4,'Cut Weight','The hardest battle happens before the fight as Taylor pushes his body past a safe limit.',45 FROM seasons se JOIN series s ON s.id_series=se.id_series JOIN titles t ON t.id_title=s.id_title WHERE t.type='TV Show' AND lower(t.title)=lower('The Cage') AND se.season_number=1 ORDER BY se.id_season LIMIT 1 ON CONFLICT(id_season,episode_number) DO UPDATE SET title=excluded.title,description=excluded.description,duration=excluded.duration,deleted_at=NULL,updated_at=now();
INSERT INTO episodes(id_season,episode_number,title,description,duration) SELECT se.id_season,5,'Center of the Cage','Under the brightest lights of his career, Taylor must trust the team that carried him there.',47 FROM seasons se JOIN series s ON s.id_series=se.id_series JOIN titles t ON t.id_title=s.id_title WHERE t.type='TV Show' AND lower(t.title)=lower('The Cage') AND se.season_number=1 ORDER BY se.id_season LIMIT 1 ON CONFLICT(id_season,episode_number) DO UPDATE SET title=excluded.title,description=excluded.description,duration=excluded.duration,deleted_at=NULL,updated_at=now();
